seen={}
for r in roots:
    for d in sorted(glob.glob(r+'/wf_*')):
        run=os.path.basename(d)
        if run in seen and os.path.exists(d+'/journal.jsonl') and len(os.listdir(seen[run]))>=len(os.listdir(d)): continue
        seen[run]=d
