    j=d+'/journal.jsonl'
    if not os.path.exists(j): continue
    ph=collections.OrderedDict()
    for l in open(j):
        e=json.loads(l)
        if e.get('type')=='started': ph.setdefault(e.get('phase'),[]).append((e['agentId'],e.get('label')))
    # timestamps from agent files
    ts=[];
    per={}
    for p,ags in ph.items():
        s=[];en=[];tok=0
        for a,lab in ags:
            f=f'{d}/agent-{a}.jsonl'
            if not os.path.exists(f): continue
            for l in open(f):
                try:x=json.loads(l)
                except:continue
                t=x.get('timestamp')
                if t: s.append(t)
                u=(x.get('message') or {}).get('usage') if isinstance(x.get('message'),dict) else None
                if u: tok+=u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0)+u.get('output_tokens',0)
        per[p]=(min(s) if s else None,max(s) if s else None,tok,len(ags))
    out.append((run,d,per))
out.sort(key=lambda o:min([v[0] for v in o[2].values() if v[0]] or ['z']))
for run,d,per in out:
    print(run,'live' if d.startswith('/root') else 'bak',list(per.keys())[:12])
